#!/bin/sh
# Name: Paperless
# Author: KOReader-Paperless
# Icon: data:image/png;base64,
# DontUseFBInk

# Leave a timestamped marker for the KOReader Paperless plugin, which opens
# its menu at startup when the marker is less than two minutes old.
date +%s > /tmp/paperless.autostart
/var/local/kmc/bin/kpm launch koreader --asap
